## [LeetCode 20. 有效的括号](https://leetcode.cn/problems/valid-parentheses/)

## Thinking


## 解法一（）
`C++写法`
```c++
class Solution {
public:
    bool isValid(string s) {
        stack<char> stk;
        for (int i = 0; i < s.length(); i ++ )
        {   
            if (s[i] == '(' || s[i] == '[' || s[i] == '{') stk.push(s[i]);
            else{
                if (stk.size() && abs(stk.top() - s[i]) <= 2) stk.pop(); //匹配
                else return false;
            }

        }
        return stk.empty();
    }
};
```
`Python写法`
```py
class Solution:
    def isValid(self, s: str) -> bool:
        stack = []
        for char in s:
            if char in "([{":
                stack.append(char)
            else:
                if stack and abs(ord(stack[-1]) - ord(char)) <= 2:
                    stack.pop()
                else:
                    return False
        return len(stack) == 0
```

