class Solution {
public:
    bool isPalindrome(int x) {
        if (x < 0 || x && x % 10 == 0) return false;
        int s = 0;
        while (s <= x){
            s = s * 10 + x % 10;
            if (s == x || s == x / 10) return true; // // 分别处理整数长度是奇数或者偶数的情况
            x /= 10;
        }
        return false;
    }
};
```

