    int i = l - 1, j = r + 1, x = q[l + r >> 1]; // 取中点 要注意此处 为什么是i = l - 1, j = r + 1
    while (i < j) {
        do i++; while (q[i] < x);
        do j--; while (q[j] > x);
        if (i < j) swap(q[i], q[j]);
    }

    quick_sort(q, l, j);
    quick_sort(q, j + 1, r);
}


