def merge_sort(data, l, r):
    if l >= r:
        return
    mid = (l + r) // 2  # 整除
    merge_sort(data, l, mid)
    merge_sort(data, mid + 1, r)
    temp = []
    i, j = l, mid + 1
    while (i <= mid) and (j <= r):
        if data[i] <= data[j]:
            temp.append(data[i])
            i += 1
        else:
            temp.append(data[j])
            j += 1
    temp += data[i:mid + 1]
    temp += data[j:r + 1]
    data[l:r + 1] = temp


