==整数二分算法模板==
```cpp
bool check(int x) {/* ... */} // 检查x是否满足某种性质

// 区间[l, r]被划分成[l, mid]和[mid + 1, r]时使用：
int bsearch_1(int l, int r)
{
    while (l < r)
    {
        int mid = l + r >> 1;
        if (check(mid)) r = mid;    // check()判断mid是否满足性质
        else l = mid + 1;
    }
    return l;
}
// 区间[l, r]被划分成[l, mid - 1]和[mid, r]时使用：
int bsearch_2(int l, int r)
{
    while (l < r)
    {
        int mid = l + r + 1 >> 1;
        if (check(mid)) l = mid;
        else r = mid - 1;
    }
    return l;
}
```
>二分的结果一定有解。
## 2.2 浮点数二分
==浮点数二分算法模板1==
```cpp
#include <iostream>

using namespace std;

int main()
{
    double x;
    cin >> x;

    double l = -x, r = x;
    while(r - l > 1e-8) //也可for迭代100次
    {
        double mid = (l + r) / 2 ;
        if(mid * mid  >= x ) r = mid;
        else l = mid;
    }
    //如果题目要求保留4位小数 r - l > 1e-6
    //如果题目要求保留5位小数 r - l > 1e-5
    //如果题目要求保留6位小数 r - l > 1e-8
    printf("%lf\n", l);
}
```

